class Solution {
  public int minCost(int[] nums) {
    int n = nums.length;
    int[][] dp = new int[n + 1][n + 3];
    for (int i = n; i >= 1; i--) {
      for (int j = 0; j < i; j++) {
        if (i >= n - 1) {
          int mx = nums[j];
          for (int t = i; t < n; t++) mx = Math.max(mx, nums[t]);
          dp[j][i] = mx;
        } else {
          int a = Math.max(nums[j], nums[i]) + dp[i + 1][i + 2];
          int b = Math.max(nums[j], nums[i + 1]) + dp[i][i + 2];
          int c = Math.max(nums[i], nums[i + 1]) + dp[j][i + 2];
          dp[j][i] = Math.min(a, Math.min(b, c));
        }
      }
    }
    return dp[0][1];
  }
}
